input.command:
cd /app && cat > /tmp/break.sql <<'EOF'
.timer on
SELECT count(*) FROM (WITH sc AS (SELECT wordid, synsetid, COUNT(*) AS sense_count FROM senses GROUP BY wordid, synsetid) SELECT * FROM sc);
SELECT count(*) FROM (WITH sc AS (SELECT wordid, synsetid, COUNT(*) AS sense_count FROM senses GROUP BY wordid, synsetid) SELECT sc.wordid FROM sc JOIN synsets syn ON syn.synsetid=sc.synsetid GROUP BY sc.wordid HAVING COUNT(*)>=2 AND COUNT(DISTINCT syn.domainid)>=2 AND SUM(sc.sense_count)>=2);
SELECT count(*) FROM (WITH sc AS (SELECT wordid, synsetid, COUNT(*) AS sense_count FROM senses GROUP BY wordid, synsetid), wa AS (SELECT sc.wordid FROM sc JOIN synsets syn ON syn.synsetid=sc.synsetid GROUP BY sc.wordid HAVING COUNT(*)>=2 AND COUNT(DISTINCT syn.domainid)>=2 AND SUM(sc.sense_count)>=2), ranked AS (SELECT sc.wordid, sc.synsetid, sc.sense_count, ROW_NUMBER() OVER (PARTITION BY sc.wordid ORDER BY sc.sense_count DESC, sc.synsetid ASC) rn FROM sc JOIN wa ON wa.wordid=sc.wordid) SELECT * FROM ranked);
EOF
sqlite3 oewn.sqlite < /tmp/break.sql

cd /app && cat > /tmp/prof.sql <<'EOF'
.timer on
SELECT count(*) FROM (SELECT wordid, synsetid, COUNT(*) c FROM senses GROUP BY wordid, synsetid);
SELECT count(*) FROM (SELECT s.wordid, s.synsetid, syn.domainid, syn.posid FROM senses s JOIN synsets syn ON syn.synsetid=s.synsetid);
WITH sc AS (SELECT wordid, synsetid, COUNT(*) AS sense_count FROM senses GROUP BY wordid, synsetid) SELECT count(*) FROM (SELECT sc.wordid FROM sc JOIN synsets syn ON syn.synsetid=sc.synsetid GROUP BY sc.wordid HAVING COUNT(*)>=2 AND COUNT(DISTINCT syn.domainid)>=2 AND SUM(sc.sense_count)>=2);
EOF
sqlite3 oewn.sqlite < /tmp/prof.sql
